videosResource
  .command("set-thumbnail")
  .description("Set a video's thumbnail")
  .argument("<id>", "id")
  .option("--inpoint-ms <v>", "Pick a video frame as the thumbnail: time in ms on the video's playback timeline (cuts applied, cumulative across clips). Clears any previously uploaded thumbna")
  .option("--source-id <v>", "Use an uploaded image as the thumbnail. Source ID from POST /v1/sources (kind: 'image'); upload the image bytes to the source's uploadUrl first. Mutually exclus")
  .option("--body <json>", "Whole JSON body (merged under the flags)")
  .option("--json", "Output as JSON")
  .option("--format <fmt>", "Output format: text, json, csv, yaml")
  .action(async (id: string, opts: Opts) => run(opts, () => (() => {
      const body: Record<string, unknown> = opts.body ? JSON.parse(opts.body as string) : {};
      const types: Record<string, string | undefined> = {"inpointMs":"integer","sourceId":"string"};
      for (const k of Object.keys(types)) {
        const v = opts[k.replace(/_([a-z])/g, (_, ch) => ch.toUpperCase())];
        if (typeof v === "string") body[k] = coerce(v, types[k]);
      }
      return client.put(`/v1/videos/${encodeURIComponent(id)}/thumbnail`, body);
    })()));

