webhooksResource
  .command("update-endpoint")
  .description("Update a webhook endpoint")
  .argument("<id>", "id")
  .option("--disabled <v>", "Pause or resume delivery to the endpoint")
  .option("--filter-types <v>", "New event types to deliver. Pass a non-empty array to replace the filter, or null to clear it so every event type is delivered. Omit to leave it unchanged. (JSO")
  .option("--url <v>", "New delivery URL")
  .option("--body <json>", "Whole JSON body (merged under the flags)")
  .option("--json", "Output as JSON")
  .option("--format <fmt>", "Output format: text, json, csv, yaml")
  .action(async (id: string, opts: Opts) => run(opts, () => (() => {
      const body: Record<string, unknown> = opts.body ? JSON.parse(opts.body as string) : {};
      const types: Record<string, string | undefined> = {"disabled":"boolean","filterTypes":"array","url":"string"};
      for (const k of Object.keys(types)) {
        const v = opts[k.replace(/_([a-z])/g, (_, ch) => ch.toUpperCase())];
        if (typeof v === "string") body[k] = coerce(v, types[k]);
      }
      return client.patch(`/v1/webhooks/endpoints/${encodeURIComponent(id)}`, body);
    })()));
